<?php require 'config.php'; $pageTitle='Find jobs'; $q=strtolower(trim($_GET['q']??'')); $loc=strtolower(trim($_GET['location']??'')); $jobs=array_values(array_filter(demo_jobs(),function($j)use($q,$loc){$hay=strtolower($j['title'].' '.$j['company'].' '.$j['industry'].' '.implode(' ',$j['tags']));return (!$q||str_contains($hay,$q))&&(!$loc||str_contains(strtolower($j['location']),$loc));})); require 'includes/header.php'; ?>
<section class="page-heading"><div><span class="eyebrow">FIND YOUR FIT</span><h1>Find work that <em>works for you.</em></h1><p class="muted">Explore opportunities that match your skills, interests and next step.</p></div></section>
<form class="search-bar listing-search" method="get"><span>⌕</span><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Job title, skill or company"><input name="location" value="<?=e($_GET['location']??'')?>" placeholder="Location"><button class="btn btn-primary">Search</button></form>
<div class="listing-layout"><aside class="filter-panel"><h3>Refine your search</h3><label>Employment type<select onchange="filterType(this.value)"><option value="">All types</option><option>Full-time</option><option>Internship</option><option>Trainee</option><option>Part-time</option></select></label><label>Industry<select onchange="filterIndustry(this.value)"><option value="">All industries</option><option>Technology</option><option>Marketing</option><option>Design</option></select></label><p class="tiny-note">Filters update the visible demo cards.</p></aside><section><div class="results-top"><strong><?=count($jobs)?> opportunities</strong><span class="muted">Latest matches</span></div><div class="job-list" id="job-list"><?php foreach($jobs as $job): ?><article class="job-card job-list-card" data-type="<?=e($job['type'])?>" data-industry="<?=e($job['industry'])?>"><div class="job-card-top"><span class="company-avatar"><?=e(substr($job['company'],0,1))?></span><span class="tag"><?=e($job['type'])?></span></div><h3><?=e($job['title'])?></h3><p class="company-name"><?=e($job['company'])?></p><p class="muted">⌖ <?=e($job['location'])?></p><p class="salary"><?=e($job['salary'])?></p><p class="job-desc"><?=e($job['description'])?></p><div class="tag-row"><?php foreach($job['tags'] as $tag): ?><span class="tag"><?=e($tag)?></span><?php endforeach; ?></div><a class="btn btn-outline full" href="job-detail.php?id=<?=e($job['id'])?>">View job & apply →</a></article><?php endforeach; ?><?php if(!$jobs): ?><div class="empty-state"><span>⌕</span><h3>No matching jobs yet</h3><p>Try a different keyword or location.</p><a href="jobs.php" class="text-link">Clear search</a></div><?php endif; ?></div></section></div>
<script>function filterType(v){document.querySelectorAll('.job-list-card').forEach(c=>c.hidden=!!v&&c.dataset.type!==v)}function filterIndustry(v){document.querySelectorAll('.job-list-card').forEach(c=>c.hidden=(!!v&&c.dataset.industry!==v)||(!!document.querySelector('.filter-panel select').value&&c.dataset.type!==document.querySelector('.filter-panel select').value))}</script>
<?php require 'includes/footer.php'; ?>
